            .nop();
        final FailableFunction<Object, Integer, IOException> nopFailableFunction = FailableFunction.nop();
        //
        try {
    failingBiFunctionTest.andThen(failingFunction).apply(null, null);
    fail("IOException");
} catch (IOException e) {
}
    }

